from lib import *
S = SS('k1')
PIPE = [['认证', '谁?'], ['鉴权', '能不能?'], ['变更准入', 'admit'], ['对象校验', '422'], ['校验准入', 'validate'], ['etcd', '落盘']]
PANELS = [('f', 'flow', '请求经过的关卡'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
L2 = S(2)[:2] + [l for l in S(2) if any(x in l for x in ('metadata.uid', 'spec.dnsPolicy', 'spec.priority', 'schedulerName', 'serviceAccountName', 'tolerations[0].key', 'tolerations[0].tolerationSeconds', 'volumes[0].name', 'imagePullPolicy'))] + S(2)[-1:]
steps = [
    step("同一个 POST /pods,只换身份和请求体:假令牌 → 401 Unauthorized;不带令牌 → 403(匿名用户 system:anonymous 到鉴权才被拒);没有 RBAC 权限的 ServiceAccount(请求体还是错的)→ 403,不是 422;有权限但对象不合法又违反 restricted → 422 Invalid;有权限、对象合法、违反 restricted → 403 violates PodSecurity;都满足 → 201。", f=fl(PIPE, mark=[0, 1, 3, 4], done=[5]), t=tl(S(1), mark=lidx(S(1), 'HTTP 401', 'HTTP 422', 'violates PodSecurity'), done=lidx(S(1), 'HTTP 201')), kv=KV([['401', '令牌认不出来,连身份都没有'], ['403(第 2、3 行)', '鉴权拒绝,发生在对象校验之前'], ['422', '对象不合法,发生在 PodSecurity 之前'], ['403(第 5 行)', '对象合法,被校验型准入拒绝']], ['422'])),
    step("--dry-run=server:提交 13 个字段,服务端回来 49 个(不含 status),多出 36 个——serviceAccountName、kube-api-access-xxxxx 这个 projected 卷、两条 tolerationSeconds=300 的容忍、priority=0、dnsPolicy、schedulerName 都是服务端补的。回来的对象有 uid 和 creationTimestamp,但紧接着 kubectl get pod k1-dry 得到 NotFound。", f=dict(fl(PIPE, cur=[2], done=[0, 1, 3, 4]), dim=[5]), t=tl(L2, mark=lidx(L2, 'serviceAccountName', 'tolerations[0]', 'volumes[0].name'), done=lidx(L2, 'NotFound')), kv=KV([['13 → 49', '服务端补了 36 个字段'], ['干跑', '走完准入和校验'], ['不落盘', 'get 得到 NotFound']], ['13 → 49'])),
    step("创建一个 Pod 前后各取一次 /metrics:计数增加的准入控制器里,变更阶段(type=admit)有 15 个,校验阶段(type=validate)有 11 个。ServiceAccount、Priority、LimitRanger、RuntimeClass 两个阶段都出现;PodSecurity、ResourceQuota 只在校验阶段;集群里没有配置任何 webhook,MutatingAdmissionWebhook 和 ValidatingAdmissionWebhook 也照样被调用。", f=fl(PIPE, cur=[2, 4], done=[0, 1, 3]), t=tl(S(3), mark=lidx(S(3), 'type=admit'), done=lidx(S(3), 'type=validate')), kv=KV([['type=admit', '15 个,可以改对象'], ['type=validate', '11 个,只能放行或拒绝'], ['PodSecurity / ResourceQuota', '只在校验阶段']], ['type=validate'])),
    step("真正创建之后,etcd 的 /registry/pods/k1/ 下有 k1-real 和 t201 两个 key,干跑的 k1-dry 不在;k1-real 的 resourceVersion 是 1078,uid 一个;干跑返回的对象有 uid、有 creationTimestamp,但没有 resourceVersion——这个字段是写进 etcd 时才产生的。", f=fl(PIPE, mark=[5], done=[0, 1, 2, 3, 4]), t=tl(S(4), mark=lidx(S(4), "k1-real'", 'resourceVersion=1078'), done=lidx(S(4), 'resourceVersion=(无)')), kv=KV([['/registry/pods/k1/', '只有真正创建的两个 Pod'], ['resourceVersion', '落盘才有,干跑没有'], ['uid', '干跑也会生成']], ['resourceVersion'])),
]
A = mkartk('k1', 1, 'Kubernetes,API Server,认证,鉴权,准入控制,etcd,真实验证,动画演示',
    '在 kind 起的真实 Kubernetes v1.37.0 集群里实测 API Server 的请求链:同一个 POST /pods 换身份和请求体分别得到 401、403、422、403 和 201,证明鉴权先于对象校验、对象校验先于 PodSecurity 准入;--dry-run=server 把提交的 13 个字段补成 49 个但不落盘;创建一个 Pod 时调用了 15 个变更型和 11 个校验型准入控制器;只有真正创建后 etcd 里才有 key、才有 resourceVersion。',
    '一次 kubectl create 到底在 API Server 里经过了哪几道关?这篇不画图纸,而是用 curl 直接打 API,让同一个请求在不同关卡被拒绝,从状态码和报错文字反推顺序;再用服务端干跑、/metrics 和 etcd 里的 key 看准入改了什么、什么时候才真正落盘。',
    [('401 → 403 → 422 → 403', '依次在认证、鉴权、对象校验、校验型准入被拒绝时的 HTTP 状态码'), ('13 → 49', '--dry-run=server 回来的 Pod 比提交的多出 36 个字段(不含 status)'), ('15 + 11', '创建一个 Pod 时被调用的变更型 + 校验型准入控制器个数')],
    [('四道关卡各自的拒绝', '<p>假令牌是 <b>401</b>:连“你是谁”都没认出来。不带令牌却是 <b>403</b>:kubeadm 集群默认允许匿名访问,匿名请求被认成 <code>system:anonymous</code>,一直走到鉴权才因为没有 RBAC 权限被拒。</p><p>第 3 行的请求体本来就有错,服务端回的却是 403 而不是 422——鉴权排在对象校验前面,没有权限的人拿不到“你的对象哪里写错了”这类信息。第 4 行有权限,对象既不合法(端口 99999)又不满足 restricted,返回 <b>422</b> 而不是 403:对象校验排在 PodSecurity 这类校验型准入前面。只有对象合法,PodSecurity 才有机会说 403(第 5 行)。</p>'),
     ('服务端干跑:准入改了什么', '<p><code>--dry-run=server</code> 会把请求完整走一遍认证、鉴权、准入和校验,只是不写 etcd。提交的 13 个字段回来变成 49 个:<code>imagePullPolicy</code>、<code>restartPolicy</code>、<code>dnsPolicy</code>、<code>terminationGracePeriodSeconds</code>、<code>schedulerName</code> 是 API 的默认值;<code>serviceAccountName</code> 和 <code>kube-api-access-xxxxx</code> 这个 projected 卷、两条 <code>tolerationSeconds: 300</code> 的容忍、<code>priority: 0</code> 与 <code>preemptionPolicy</code> 是准入控制器按各自职责补上的。</p><p>回来的对象带 <code>uid</code> 和 <code>creationTimestamp</code>,但紧接着 <code>kubectl get</code> 得到 NotFound——干跑没有留下任何东西。</p>'),
     ('哪些准入控制器被调用', '<p>变更阶段(<code>type=admit</code>)有 15 个,校验阶段(<code>type=validate</code>)有 11 个。<code>ServiceAccount</code>、<code>Priority</code>、<code>LimitRanger</code>、<code>RuntimeClass</code> 在两个阶段都出现;<code>PodSecurity</code>、<code>ResourceQuota</code> 只出现在校验阶段,它们不能改对象,只能放行或拒绝。集群里一个 webhook 都没配,<code>MutatingAdmissionWebhook</code> 和 <code>ValidatingAdmissionWebhook</code> 也照样被调用——它们遍历到的 webhook 列表是空的而已。</p><p>这份名单来自两次 <code>/metrics</code> 之间计数增加的控制器,窗口内集群里还有别的写入,所以它是“被调用过”的集合,不是只属于这一个请求的。</p>'),
     ('落盘才有 resourceVersion', '<p>真正创建之后,etcd 的 <code>/registry/pods/k1/</code> 下有 <code>k1-real</code> 和 <code>t201</code> 两个 key,干跑的 <code>k1-dry</code> 没有。<code>resourceVersion</code> 是写进 etcd 时才产生的(这次是 1078),干跑返回的对象没有这个字段;<code>uid</code> 和创建时间则在干跑里就已经生成。</p><p>顺序因此是:认证 → 鉴权 → 变更准入 → 对象校验 → 校验型准入 → 写 etcd,每一道关卡拒绝时返回的状态码和报错措辞都不同,排查时可以反过来用它判断请求死在了哪一步。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(1 个控制面 + 2 个工作节点,Kubernetes v1.37.0,默认的准入插件和 kubeadm 默认的匿名访问设置);用 curl 直接请求 apiserver 的回环端口,管理员身份用绑定了 cluster-admin 的临时 ServiceAccount 令牌,无权限身份用 k1 命名空间的 default ServiceAccount 令牌;k1 命名空间带 pod-security.kubernetes.io/enforce=restricted;etcd 里的 key 用 etcd 静态 Pod 里的 etcdctl 读出;每种情形各一次',
     '没有验证:变更准入先于对象校验这个顺序(本文只直接验证了鉴权先于校验、校验先于校验型准入);每个新增字段具体是哪个准入控制器补的(按各控制器的职责对应,没有逐个关闭插件);配置了 webhook、ValidatingAdmissionPolicy 之后的顺序(后面有专门的文章);审计日志里这些阶段的记录;聚合 API 与 CRD 请求的差别'],
    '请求链', PANELS)
